create table public.academic_catalog(id uuid primary key default gen_random_uuid(), kind text not null, name text not null, stage text, sort_order integer not null default 0, unique(kind,name,stage));
grant select on public.academic_catalog to authenticated; grant all on public.academic_catalog to service_role;
alter table public.academic_catalog enable row level security;
create policy academic_catalog_read on public.academic_catalog for select to authenticated using(auth.uid() is not null);
insert into academic_catalog(kind,name,stage,sort_order) values('year','1448/1449',null,1),('year','1449/1450',null,2),('term','الفصل الدراسي الأول',null,1),('term','الفصل الدراسي الثاني',null,2),('stage','رياض الأطفال',null,1),('stage','الابتدائية',null,2),('stage','المتوسطة',null,3),('stage','الثانوية',null,4),('grade','KG1','رياض الأطفال',1),('grade','KG2','رياض الأطفال',2),('grade','KG3','رياض الأطفال',3),('grade','أول','الابتدائية',1),('grade','ثاني','الابتدائية',2),('grade','ثالث','الابتدائية',3),('grade','رابع','الابتدائية',4),('grade','خامس','الابتدائية',5),('grade','سادس','الابتدائية',6),('grade','أول','المتوسطة',1),('grade','ثاني','المتوسطة',2),('grade','ثالث','المتوسطة',3),('grade','أول','الثانوية',1),('grade','ثاني','الثانوية',2),('grade','ثالث','الثانوية',3);
create or replace function public._academic_owner_guard() returns trigger language plpgsql set search_path=public as $$ declare s uuid; begin s:=case when tg_op='DELETE' then old.school_id else new.school_id end; if not is_org_owner(school_org(s)) then raise exception 'محددات الدراسة من صلاحية مالك المجموعة فقط'; end if; if tg_op='UPDATE' and new.school_id<>old.school_id then raise exception 'لا يسمح بنقل المحدد إلى فرع آخر'; end if; if tg_op='DELETE' then return old; end if; return new; end $$;
create trigger academic_year_owner before insert or update or delete on public.academic_years for each row execute function public._academic_owner_guard();
create trigger academic_term_owner before insert or update or delete on public.terms for each row execute function public._academic_owner_guard();
create trigger academic_stage_owner before insert or update or delete on public.stages for each row execute function public._academic_owner_guard();
create trigger academic_grade_owner before insert or update or delete on public.grades for each row execute function public._academic_owner_guard();
create or replace function public._section_vice_ok(_school uuid) returns boolean language sql stable security invoker set search_path=public as $$ select is_org_owner(school_org(_school)) or exists(select 1 from memberships m where m.user_id=auth.uid() and m.school_id=_school and m.org_id=school_org(_school) and m.role='vice_principal' and m.is_active and not m.branch_suspended and exists(select 1 from schools where id=_school and is_active)) $$;
create or replace function public._academic_section_guard() returns trigger language plpgsql set search_path=public as $$ declare s uuid; begin s:=case when tg_op='DELETE' then old.school_id else new.school_id end; if not _section_vice_ok(s) then raise exception 'تكوين الشعب من صلاحية الوكيل ضمن فرعه'; end if; if tg_op='DELETE' then return old; end if; if tg_op='UPDATE' and new.school_id<>old.school_id then raise exception 'لا يسمح بنقل الشعبة إلى فرع آخر'; end if; if not exists(select 1 from grades g join stages st on st.id=g.stage_id where g.id=new.grade_id and g.school_id=s and st.school_id=s) or not exists(select 1 from academic_years y where y.id=new.year_id and y.school_id=s) then raise exception 'الصف أو العام غير متاح للفرع'; end if; return new; end $$;
create trigger academic_section_guard before insert or update or delete on public.sections for each row execute function public._academic_section_guard();
create policy section_vice_insert on public.sections for insert to authenticated with check(_section_vice_ok(school_id));
create policy section_vice_update on public.sections for update to authenticated using(_section_vice_ok(school_id)) with check(_section_vice_ok(school_id));
create policy section_vice_delete on public.sections for delete to authenticated using(_section_vice_ok(school_id));
revoke all on function public._academic_owner_guard(),public._academic_section_guard() from public,anon,authenticated;
revoke all on function public._section_vice_ok(uuid) from public,anon; grant execute on function public._section_vice_ok(uuid) to authenticated,service_role;